body.script:
(function(){
  var phone=document.querySelector('.phone');
  var titleBar=document.getElementById('titleBar');
  if(!phone||!titleBar)return;
  var ticking=false;
  function update(){
    var y=phone.scrollTop;
    if(y>40)titleBar.classList.add('visible');else titleBar.classList.remove('visible');
    ticking=false;
  }
  phone.addEventListener('scroll',function(){
    if(!ticking){ticking=true;requestAnimationFrame(update)}
  },{passive:true});
  update();
})();
